"use strict";

/*---------------------------------------------------------------------*/
/*    import                                                           */
/*---------------------------------------------------------------------*/
import * as assert from "assert";
import { Parser, ast, generate } from "@hop/hopc";

describe('hop()', function () {
   const parser = new Parser();
   const parseString = parser.parseString.bind(parser);
   
   it('parse boolean', function () {
      assert.equal(generate(parseString("true;")), "true;");
   });
   it('parse number', function () {
      assert.equal(generate(parseString("1234;")), "1234;");
   });
   it('parse hexa', function () {
      assert.equal(generate(parseString("0xf1234;")), "0xf1234;");
   });
   it('parse float', function () {
      assert.equal(generate(parseString("1234.53;")), "1234.53;");
   });
   it('parse bigint', function () {
      assert.equal(generate(parseString("1234n;")), "1234n;");
   });
   it('parse expression', function () {
      assert.equal(generate(parseString("1+x;")), "1 + x;");
   });
   it('parse expression', function () {
      assert.equal(generate(parseString("1+x.length+'foo'.length;")).toString(), "1 + x.length + 'foo'.length;");
   });
   it('parse chaining', function () {
      assert.equal(generate(parseString("y?.z;")), "y?.z;");
   });
   it('export', function () {
      assert.equal(generate(parseString("export const x = 3;")).toString(), "const x=3;\nexport { x };");
   });
   console.error("OR=", generate(parseString("x ||= 3;")).toString());
   it('logical or', function () {
      assert.equal(generate(parseString("x ||= 3;")).toString(), "x ||= 3");
   });
   it('logical and', function () {
      assert.equal(generate(parseString("x &&= {};")).toString(), "x &&= {}");
   });
   it('nullish', function () {
      assert.equal(generate(parseString("x ??= 7.8;")).toString(), "x ??= 7.8");
   });
});
